def language():
    return getattr(g, 'language', 'pl') if has_request_context() else 'pl'


def translate(text):
    return TRANSLATIONS.get(text, text) if language() == 'en' else text


def counted(count, one, few, many):
    noun = one if count == 1 else few if count % 10 in (2, 3, 4) and count % 100 not in (12, 13, 14) else many
    number = f'{count:,}'.replace(',', ' ')
    return f'{number} {translate(noun)}'
